/** The features as rows: text beside a picture (the rows layout of FeatureGrid). Icons are Lucide names. */
import { For, type JSX } from "solid-js";
import { Box } from "../primitives/box/box";
import { Grid } from "../primitives/grid/grid";
import { LucideIcon } from "../primitives/lucide-icon/lucide-icon";
import { Stack } from "../primitives/stack/stack";
import { Text } from "../primitives/text/text";
import { Title } from "../primitives/title/title";
import { MediaFrame } from "../components/media-frame";
import { cn } from "../utils";
import type { Feature } from "../blocks/feature-grid.types";

export type FeatureRowsProps = {
  features: Feature[];
  mediaSide?: "end" | "start" | "alternate";
};

export function FeatureRows({ features, mediaSide = "end" }: FeatureRowsProps) {
  return (
    <Stack gap="8" align="stretch" data-testid="feature-rows">
      <For each={features ?? []}>{(feature) => (
        <Grid cols="1-2" class="group items-center gap-8" data-testid="feature-card">
          <Stack gap="2" class="min-w-0">
            <LucideIcon name={feature.icon} size={24} />
            <Title as={3} size="xl" weight="bold">
              {feature.title}
            </Title>
            <Text size="base" class="text-muted-foreground">
              {feature.text}
            </Text>
          </Stack>
          <Box
            class={cn(
              "w-full min-w-0",
              (
                (mediaSide as string) === "start" ? "md:order-first"
                : (mediaSide as string) === "alternate" ? "md:group-even:order-first"
                : ""
              )
            )}
          >
            <MediaFrame alt={feature.title} ratio="4/3" />
          </Box>
        </Grid>
      )}</For>
    </Stack>
  );
}
